<?php
declare(strict_types=1);
require_once __DIR__.'/api/lib/helpers.php';
function blog_post_e(string $value):string{return htmlspecialchars($value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$slug=trim((string)($_GET['slug']??''));
if($slug===''){$first=get_db()->query('SELECT slug FROM cms_entries WHERE entry_type="blog" AND status="published" ORDER BY COALESCE(published_at,created_at) DESC LIMIT 1')->fetchColumn();if($first){header('Location: /conscious/blog-post?slug='.rawurlencode((string)$first));exit;}}
$stmt=get_db()->prepare('SELECT slug,title,content_json,published_at FROM cms_entries WHERE entry_type="blog" AND slug=:slug AND status="published" AND (starts_at IS NULL OR starts_at<=UTC_TIMESTAMP()) AND (ends_at IS NULL OR ends_at>=UTC_TIMESTAMP()) LIMIT 1');$stmt->execute(['slug'=>$slug]);$post=$stmt->fetch();
if(!$post){http_response_code(404);$post=['slug'=>'','title'=>'Story not found','content_json'=>json_encode(['excerpt'=>'This story is no longer available.','body'=>[]]),'published_at'=>date('Y-m-d H:i:s')];}
$content=json_decode((string)$post['content_json'],true);if(!is_array($content))$content=[];$body=is_array($content['body']??null)?$content['body']:[];
$shareBase=APP_URL!==''?APP_URL:request_origin();
$shareUrl=rtrim($shareBase,'/').'/blog-post?slug='.rawurlencode($slug);
?>
<!DOCTYPE html><html lang="en" dir="ltr"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#4B572C"><meta name="description" content="<?=blog_post_e((string)($content['excerpt']??''))?>"><title><?=blog_post_e((string)$post['title'])?> — Conscious India</title>
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Serif+Display:ital@0;1&family=Poppins:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><link rel="stylesheet" href="/conscious/assets/css/bharatcraft.css"><link rel="stylesheet" href="/conscious/assets/css/blog-editorial.css?v=20261026-1"></head>
<body><div id="bc-preloader" role="status" aria-label="Loading Conscious India"><img src="/conscious/assets/images/symbol.png" alt="" class="bc-preloader-symbol" width="90" height="90"><div class="bc-preloader-brand">Conscious India</div><div class="bc-preloader-chakra"></div></div><?php require __DIR__.'/includes/public-header.php'; ?>
<main id="main-content"><article class="ci-article"><header class="ci-article-header"><div class="container ci-article-header-inner"><a class="ci-back-link" href="/conscious/blog"><i class="fa-solid fa-arrow-left"></i> All stories</a><p class="ci-eyebrow"><?=blog_post_e((string)($content['category']??'Conscious living'))?></p><h1><?=blog_post_e((string)$post['title'])?></h1><p class="ci-article-deck"><?=blog_post_e((string)($content['excerpt']??''))?></p><div class="ci-article-byline"><span>By <?=blog_post_e((string)($content['author']??'Conscious India Editorial'))?></span><i></i><time><?=blog_post_e(date('d F Y',strtotime((string)$post['published_at'])))?></time><i></i><span><?=blog_post_e((string)($content['reading_minutes']??'5'))?> min read</span></div></div></header>
<figure class="ci-article-hero"><img src="<?=blog_post_e((string)($content['hero_image']??'/conscious/assets/images/about/artisan-weaving-natural-basket.jpg'))?>" alt="<?=blog_post_e((string)($content['hero_alt']??$post['title']))?>"><figcaption><?=blog_post_e((string)($content['image_caption']??''))?></figcaption></figure>
<div class="ci-article-layout container"><aside class="ci-article-aside"><span>Share this story</span><a href="https://wa.me/?text=<?=rawurlencode((string)$post['title'].' '.$shareUrl)?>" aria-label="Share on WhatsApp"><i class="fa-brands fa-whatsapp"></i></a><a href="mailto:?subject=<?=rawurlencode((string)$post['title'])?>" aria-label="Share by email"><i class="fa-regular fa-envelope"></i></a></aside><div class="ci-article-body">
<?php foreach($body as $block):if(!is_array($block))continue;$type=(string)($block['type']??'paragraph');if($type==='heading'):?><h2><?=blog_post_e((string)($block['text']??''))?></h2><?php elseif($type==='quote'):?><blockquote><p><?=blog_post_e((string)($block['text']??''))?></p><?php if(!empty($block['cite'])):?><cite><?=blog_post_e((string)$block['cite'])?></cite><?php endif;?></blockquote><?php elseif($type==='list'&&is_array($block['items']??null)):?><ul><?php foreach($block['items'] as $item):?><li><?=blog_post_e((string)$item)?></li><?php endforeach;?></ul><?php else:?><p><?=blog_post_e((string)($block['text']??''))?></p><?php endif;endforeach;if(!$body):?><p>This story is being prepared. Please return soon.</p><?php endif;?></div></div>
<footer class="ci-article-footer"><div class="container"><p class="ci-eyebrow">Keep discovering</p><h2>Thoughtful choices begin with better stories.</h2><div><a href="/conscious/blog" class="ci-outline-button">Read more stories</a><a href="/conscious/shop" class="ci-solid-button">Explore the marketplace</a></div></div></footer></article></main>
